package com.lianxibu.site.domain.protocol;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.Instant;import org.junit.jupiter.api.Test;
class SourceContractTelemetryTest {
 byte[] example()throws Exception{return Files.readAllBytes(Path.of("../contracts/source-contract-telemetry-v1.example.json"));}
 byte[] change(String from,String to)throws Exception{return new String(example(),StandardCharsets.UTF_8).replace(from,to).getBytes(StandardCharsets.UTF_8);}
 @Test void publishedFictionalExampleAndClosedSchemaMatchNativeWirePort()throws Exception{var value=SourceContractTelemetry.parse(example());assertEquals("fictional-source",value.snapshot().sourceId());assertEquals(1,value.snapshot().events().size());assertEquals(1,value.snapshot().totalFailures());assertEquals(Instant.parse("2026-01-01T00:09:00Z"),value.snapshot().events().getFirst().occurredAt());assertEquals(value.payloadHash(),SourceContractTelemetry.parse(value.canonical().getBytes(StandardCharsets.UTF_8)).payloadHash());var schema=CanonicalJson.parse(Files.readAllBytes(Path.of("../contracts/source-contract-telemetry-v1.schema.json")));assertFalse(schema.get("additionalProperties").booleanValue());assertEquals(9,schema.get("required").size());assertEquals(9,schema.get("properties").size());assertEquals(200,schema.get("properties").get("events").get("maxItems").asInt());assertFalse(value.toString().contains("fictional-source"));assertThrows(UnsupportedOperationException.class,()->value.snapshot().events().clear());}
 @Test void missingUnknownDuplicateKeysAndWrongTypesAreRejected()throws Exception{assertThrows(IllegalArgumentException.class,()->SourceContractTelemetry.parse(change("\"events\":", "\"unknown\":true,\"events\":")));assertThrows(IllegalArgumentException.class,()->SourceContractTelemetry.parse(change("\"config_version\": 1", "\"config_version\": 1,\"config_version\": 1")));assertThrows(IllegalArgumentException.class,()->SourceContractTelemetry.parse(change("\"config_version\": 1", "\"config_version\": 1.0")));assertThrows(IllegalArgumentException.class,()->SourceContractTelemetry.parse(change("source-contract-telemetry-v1", "source-contract-telemetry-v2")));}
 @Test void windowSequenceAndEventTimesMustProveACompleteOrderedWindow()throws Exception{for(var pair:new String[][]{{"00:00:00.000000Z","00:00:01.000000Z"},{"00:09:00.000000Z","00:10:01.000000Z"},{"00:09:00.000000Z","00:00:00.000000Z"},{"\"total_failures\": 1","\"total_failures\": 0"},{"\"config_version\": 1","\"config_version\": 0"},{"\"sequence\": 1","\"sequence\": 9007199254740992"}})assertThrows(IllegalArgumentException.class,()->SourceContractTelemetry.parse(change(pair[0],pair[1])));var t=Instant.parse("2026-01-01T00:10:00Z");assertThrows(IllegalArgumentException.class,()->new SourceContractTelemetry.Snapshot("fictional-source",1,"00000000-0000-4000-8000-000000000001",1,t,t.minusSeconds(600),2,java.util.List.of(new SourceContractTelemetry.Event(2,t),new SourceContractTelemetry.Event(1,t))));}
 @Test void rawCapacityAndTimestampPrecisionFailClosed()throws Exception{assertThrows(IllegalArgumentException.class,()->SourceContractTelemetry.parse(new byte[32769]));assertThrows(IllegalArgumentException.class,()->SourceContractTelemetry.parse(change("00:10:00.000000Z","00:10:00Z")));assertThrows(IllegalArgumentException.class,()->SourceContractTelemetry.parse(null));}
}
